### RECURSION ###

# Please complete the function to recursively 
# calculate the nth Fibonacci number (i.e., 0, 1, 1, 2, 3, 5, 8...)
# Parameters: n - index for number in fibonacci sequence
def fibonacci(n) -> int:
    
    # Base case
	if (n == 0) {
        return 0;
    }

    # Active flow
	return n + fibonacci(n - 1) 

    # Passive flow
	cout << n << "";qq

### ITERATION ###

# Please complete the function to iteratively calculate 
# the sum of the first n natural numbers
# Parameters: n - quantity of natural numbers to consider
def sumOfNaturalNumbers(n) -> int:

    # loop header (can do for or while loop)
    while (count <= n)    :
        # loop body
		sum += n;
        count++;

    # return statement
	return sum;
qq

### RECURSION ### 

# Please complete the function to recursively check if 
# a given string is a palindrome.  (i.e., 'racecar' <--> 'racecar')
# Parameters: string - string to be checked
#           start - index for beginning of subsequence
#             end - index for end of subsequence
def isPalindrome(string, start, end) -> bool:
    
    # Base case
	if(start == end) {
    	return true;
    }

    # Active flow
    if (string[start] == string[end]) isPalindrome(string, start + 1, end - 1)
    else return false;
qq

### RECURSION ###

# Please complete the function to recursively calculate 
# whether a given integer is a palindrome (i.e., 12321, 2442)
# --- Without converting it into a string --- 
# Parameters: x - integer to test
def is_num_palindrome(x) -> bool:


    # Base case
    if(x == 1) {
        return true;
    }
   
    # Active flow
    if(x % 10 == x / 10) is_num_palindrome(x - (x/10) - ((x % 10) * 10))); 
    else return false
	qq
